CREATE TABLE [dbo].[ccInboundMsgs](	  [Msg_id] INT NOT NULL	, [Inbound_id] SMALLINT NOT NULL	, [orden] TINYINT NOT NULL	, [Type] TINYINT NOT NULL	, [queue] BIT NULL DEFAULT((0)))ALTER TABLE [dbo].[ccInboundMsgs] WITH CHECK ADD CONSTRAINT [FK_ccInboundMsgs_ccMsgFiles] FOREIGN KEY([Msg_id]) REFERENCES [dbo].[ccMsgFiles] ([msg_id])ALTER TABLE [dbo].[ccInboundMsgs] CHECK CONSTRAINT [FK_ccInboundMsgs_ccMsgFiles]ALTER TABLE [dbo].[ccInboundMsgs] WITH CHECK ADD CONSTRAINT [FK_ccInboundMsgs_ccTipoMsgs] FOREIGN KEY([Type]) REFERENCES [dbo].[ccTipoMsgs] ([tipomsg_id])ALTER TABLE [dbo].[ccInboundMsgs] CHECK CONSTRAINT [FK_ccInboundMsgs_ccTipoMsgs]ALTER TABLE [dbo].[ccInboundMsgs] WITH NOCHECK ADD CONSTRAINT [FK_ccInboundMsgs_ccInbound] FOREIGN KEY([Inbound_id]) REFERENCES [dbo].[ccInbound] ([Inbound_id])ALTER TABLE [dbo].[ccInboundMsgs] CHECK CONSTRAINT [FK_ccInboundMsgs_ccInbound]CREATE NONCLUSTERED INDEX [IX_ccInboundMsgs_3] ON [dbo].[ccInboundMsgs] ([Inbound_id] ASC, [orden] ASC, [Type] ASC)CREATE UNIQUE NONCLUSTERED INDEX [IX_ccInboundMsgs] ON [dbo].[ccInboundMsgs] ([Msg_id] ASC, [Inbound_id] ASC, [orden] ASC, [Type] ASC)CREATE NONCLUSTERED INDEX [IX_ccInboundMsgs_1] ON [dbo].[ccInboundMsgs] ([Inbound_id] ASC, [Type] ASC)CREATE NONCLUSTERED INDEX [IX_ccInboundMsgs_2] ON [dbo].[ccInboundMsgs] ([orden] ASC)